import { useRef, useState } from 'react';
import { Download, Eye, Image as ImageIcon, Loader2 } from 'lucide-react';
import html2canvas from 'html2canvas';
import useGreetingStore from '../hooks/useGreetingStore';

const PreviewExport = () => {
  const { cardText, fontSize, textColor, selectedCardTemplate } = useGreetingStore();
  const cardRef = useRef<HTMLDivElement>(null);
  const [isExporting, setIsExporting] = useState(false);
  const [showPreview, setShowPreview] = useState(false);

  const handleExport = async () => {
    if (!cardRef.current) return;
    
    setIsExporting(true);
    
    try {
      const canvas = await html2canvas(cardRef.current, {
        backgroundColor: null,
        scale: 2,
        useCORS: true,
      });
      
      const link = document.createElement('a');
      link.download = `贺卡_${new Date().toLocaleDateString()}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    } catch (error) {
      console.error('导出失败:', error);
      alert('导出失败，请重试');
    }
    
    setIsExporting(false);
  };

  const canExport = cardText && selectedCardTemplate;

  return (
    <section className="py-8 px-4">
      <div className="max-w-4xl mx-auto">
        <h2 className="text-xl font-bold text-gray-800 mb-6 flex items-center gap-2">
          <span className="w-1 h-6 bg-gradient-to-b from-pink-400 to-pink-600 rounded-full"></span>
          预览与导出
        </h2>
        
        <div className="bg-white rounded-2xl shadow-lg p-6">
          <div className="flex flex-col md:flex-row items-center justify-center gap-6">
            <button
              onClick={() => setShowPreview(true)}
              disabled={!canExport}
              className={`flex items-center gap-2 px-6 py-3 rounded-xl font-medium transition-all ${
                canExport
                  ? 'bg-gradient-to-r from-purple-500 to-purple-600 text-white hover:from-purple-600 hover:to-purple-700 shadow-lg hover:shadow-xl'
                  : 'bg-gray-200 text-gray-400 cursor-not-allowed'
              }`}
            >
              <Eye className="w-5 h-5" />
              预览贺卡
            </button>
            
            <button
              onClick={handleExport}
              disabled={!canExport || isExporting}
              className={`flex items-center gap-2 px-6 py-3 rounded-xl font-medium transition-all ${
                canExport && !isExporting
                  ? 'bg-gradient-to-r from-pink-500 to-rose-500 text-white hover:from-pink-600 hover:to-rose-600 shadow-lg hover:shadow-xl'
                  : 'bg-gray-200 text-gray-400 cursor-not-allowed'
              }`}
            >
              {isExporting ? (
                <>
                  <Loader2 className="w-5 h-5 animate-spin" />
                  导出中...
                </>
              ) : (
                <>
                  <Download className="w-5 h-5" />
                  保存为图片
                </>
              )}
            </button>
          </div>
          
          {!canExport && (
            <p className="text-center text-sm text-orange-500 mt-4 flex items-center justify-center gap-1">
              <span>⚠️</span>
              {!selectedCardTemplate && '请先选择贺卡模板'}
              {selectedCardTemplate && !cardText && '请先输入贺卡文字'}
            </p>
          )}
        </div>
        
        <div className="mt-6 bg-gradient-to-br from-pink-50 to-rose-50 rounded-2xl p-6">
          <div className="flex items-center gap-2 mb-4">
            <ImageIcon className="w-5 h-5 text-pink-500" />
            <h3 className="font-semibold text-gray-800">贺卡预览</h3>
          </div>
          
          <div className="flex justify-center">
            <div
              ref={cardRef}
              className="aspect-[3/4] w-full max-w-xs rounded-xl overflow-hidden flex flex-col items-center justify-center p-8 relative shadow-lg"
              style={{
                background: selectedCardTemplate?.background || 'linear-gradient(135deg, #FFE4E1 0%, #FFB6C1 100%)'
              }}
            >
              <div className="absolute top-4 left-4 text-4xl opacity-30">
                ✨
              </div>
              <div className="absolute top-4 right-4 text-4xl opacity-30">
                💝
              </div>
              <div className="absolute bottom-4 left-4 text-4xl opacity-30">
                🌟
              </div>
              <div className="absolute bottom-4 right-4 text-4xl opacity-30">
                🎀
              </div>
              
              <div className="text-center z-10">
                {cardText ? (
                  <p
                    className="leading-relaxed max-w-full"
                    style={{
                      fontSize: `${fontSize}px`,
                      color: textColor,
                      textShadow: textColor === '#FFFFFF' ? '1px 1px 2px rgba(0,0,0,0.3)' : 'none'
                    }}
                  >
                    {cardText}
                  </p>
                ) : (
                  <p className="text-gray-400 text-lg">请先输入文字或选择祝福语</p>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
      
      {showPreview && canExport && (
        <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4" onClick={() => setShowPreview(false)}>
          <div
            className="aspect-[3/4] max-w-lg w-full rounded-2xl overflow-hidden shadow-2xl"
            onClick={(e) => e.stopPropagation()}
          >
            <div
              className="w-full h-full flex flex-col items-center justify-center p-8 relative"
              style={{
                background: selectedCardTemplate?.background || 'linear-gradient(135deg, #FFE4E1 0%, #FFB6C1 100%)'
              }}
            >
              <div className="absolute top-6 left-6 text-5xl opacity-30">
                ✨
              </div>
              <div className="absolute top-6 right-6 text-5xl opacity-30">
                💝
              </div>
              <div className="absolute bottom-6 left-6 text-5xl opacity-30">
                🌟
              </div>
              <div className="absolute bottom-6 right-6 text-5xl opacity-30">
                🎀
              </div>
              
              <div className="text-center z-10">
                <p
                  className="leading-relaxed max-w-full"
                  style={{
                    fontSize: `${fontSize * 1.2}px`,
                    color: textColor,
                    textShadow: textColor === '#FFFFFF' ? '1px 1px 2px rgba(0,0,0,0.3)' : 'none'
                  }}
                >
                  {cardText}
                </p>
              </div>
            </div>
          </div>
        </div>
      )}
    </section>
  );
};

export default PreviewExport;
