import { Check } from 'lucide-react';
import { cardTemplates } from '../utils/mockData';
import useGreetingStore from '../hooks/useGreetingStore';

const CardTemplate = () => {
  const { selectedCardTemplate, setSelectedCardTemplate } = useGreetingStore();

  return (
    <section className="py-8 px-4">
      <div className="max-w-4xl mx-auto">
        <h2 className="text-xl font-bold text-gray-800 mb-6 flex items-center gap-2">
          <span className="w-1 h-6 bg-gradient-to-b from-pink-400 to-pink-600 rounded-full"></span>
          选择贺卡模板
        </h2>
        
        <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
          {cardTemplates.map((template) => (
            <button
              key={template.id}
              onClick={() => setSelectedCardTemplate(template)}
              className={`relative rounded-2xl overflow-hidden transition-all duration-300 ${
                selectedCardTemplate?.id === template.id
                  ? 'ring-4 ring-pink-400 scale-105 shadow-xl'
                  : 'hover:scale-105 shadow-lg hover:shadow-xl'
              }`}
            >
              <div
                className="aspect-[3/4] flex flex-col items-center justify-center p-6"
                style={{ background: template.background }}
              >
                <div
                  className="text-4xl mb-4"
                  style={{ color: template.accentColor }}
                >
                  💝
                </div>
                <h3
                  className="font-bold text-center"
                  style={{ color: template.textColor }}
                >
                  {template.title}
                </h3>
                <p
                  className="text-sm text-center mt-2 opacity-80"
                  style={{ color: template.textColor }}
                >
                  预览效果
                </p>
              </div>
              
              {selectedCardTemplate?.id === template.id && (
                <div className="absolute top-3 right-3 w-8 h-8 bg-white rounded-full flex items-center justify-center shadow-md">
                  <Check className="w-5 h-5 text-pink-500" />
                </div>
              )}
            </button>
          ))}
        </div>
      </div>
    </section>
  );
};

export default CardTemplate;
