import { Cake, Sparkles, Moon, GraduationCap, Heart, MessageCircle, Users, BookOpen, Briefcase } from 'lucide-react';
import { scenes, recipients } from '../utils/mockData';
import useGreetingStore from '../hooks/useGreetingStore';

const iconMap: Record<string, React.ComponentType<{ className?: string }>> = {
  Cake,
  Sparkles,
  Moon,
  GraduationCap,
  Heart,
  MessageCircle,
  Users,
  BookOpen,
  Briefcase,
};

const SceneSelector = () => {
  const { selectedScene, selectedRecipient, setSelectedScene, setSelectedRecipient } = useGreetingStore();

  return (
    <section className="py-8 px-4">
      <div className="max-w-4xl mx-auto">
        <h2 className="text-xl font-bold text-gray-800 mb-6 flex items-center gap-2">
          <span className="w-1 h-6 bg-gradient-to-b from-pink-400 to-pink-600 rounded-full"></span>
          选择场景
        </h2>
        
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4 mb-8">
          {scenes.map((scene) => {
            const Icon = iconMap[scene.icon] || Heart;
            return (
              <button
                key={scene.id}
                onClick={() => setSelectedScene(scene)}
                className={`flex flex-col items-center gap-2 p-4 rounded-2xl transition-all duration-300 ${
                  selectedScene?.id === scene.id
                    ? 'bg-gradient-to-br from-pink-400 to-pink-600 text-white shadow-lg scale-105'
                    : 'bg-white hover:bg-pink-50 hover:scale-105 shadow-md'
                }`}
              >
                <div
                  className={`w-12 h-12 rounded-xl flex items-center justify-center ${
                    selectedScene?.id === scene.id
                      ? 'bg-white/20'
                      : 'bg-gray-100'
                  }`}
                  style={{ backgroundColor: selectedScene?.id === scene.id ? 'rgba(255,255,255,0.2)' : undefined }}
                >
                  <Icon className={`w-6 h-6 ${selectedScene?.id === scene.id ? 'text-white' : scene.color}`} />
                </div>
                <span className="text-sm font-medium">{scene.name}</span>
              </button>
            );
          })}
        </div>

        <h2 className="text-xl font-bold text-gray-800 mb-4 flex items-center gap-2">
          <span className="w-1 h-6 bg-gradient-to-b from-pink-400 to-pink-600 rounded-full"></span>
          祝福对象
        </h2>
        
        <div className="flex flex-wrap gap-3">
          {recipients.map((recipient) => {
            const Icon = iconMap[recipient.icon] || Users;
            return (
              <button
                key={recipient.id}
                onClick={() => setSelectedRecipient(recipient)}
                className={`flex items-center gap-2 px-4 py-2.5 rounded-full transition-all duration-300 ${
                  selectedRecipient?.id === recipient.id
                    ? 'bg-gradient-to-r from-pink-400 to-pink-600 text-white shadow-md'
                    : 'bg-white hover:bg-pink-50 text-gray-700 shadow-sm border border-gray-100'
                }`}
              >
                <Icon className="w-4 h-4" />
                <span className="text-sm font-medium">{recipient.name}</span>
              </button>
            );
          })}
        </div>
      </div>
    </section>
  );
};

export default SceneSelector;
