import { create } from 'zustand';
import { Scene, Recipient, CardTemplate, GeneratedGreeting } from '../utils/mockData';

interface GreetingStore {
  selectedScene: Scene | null;
  selectedRecipient: Recipient | null;
  keyword: string;
  generatedGreetings: GeneratedGreeting[];
  selectedGreeting: GeneratedGreeting | null;
  selectedCardTemplate: CardTemplate | null;
  cardText: string;
  fontSize: number;
  textColor: string;
  isGenerating: boolean;

  setSelectedScene: (scene: Scene) => void;
  setSelectedRecipient: (recipient: Recipient) => void;
  setKeyword: (keyword: string) => void;
  setGeneratedGreetings: (greetings: GeneratedGreeting[]) => void;
  setSelectedGreeting: (greeting: GeneratedGreeting | null) => void;
  setSelectedCardTemplate: (template: CardTemplate) => void;
  setCardText: (text: string) => void;
  setFontSize: (size: number) => void;
  setTextColor: (color: string) => void;
  setIsGenerating: (isGenerating: boolean) => void;
  resetStore: () => void;
}

const useGreetingStore = create<GreetingStore>((set) => ({
  selectedScene: null,
  selectedRecipient: null,
  keyword: '',
  generatedGreetings: [],
  selectedGreeting: null,
  selectedCardTemplate: null,
  cardText: '',
  fontSize: 24,
  textColor: '#8B0000',
  isGenerating: false,

  setSelectedScene: (scene) => set({ selectedScene: scene }),
  setSelectedRecipient: (recipient) => set({ selectedRecipient: recipient }),
  setKeyword: (keyword) => set({ keyword }),
  setGeneratedGreetings: (greetings) => set({ generatedGreetings: greetings }),
  setSelectedGreeting: (greeting) => set({ selectedGreeting: greeting }),
  setSelectedCardTemplate: (template) => set({ selectedCardTemplate: template }),
  setCardText: (text) => set({ cardText: text }),
  setFontSize: (size) => set({ fontSize: size }),
  setTextColor: (color) => set({ textColor: color }),
  setIsGenerating: (isGenerating) => set({ isGenerating }),
  resetStore: () => set({
    selectedScene: null,
    selectedRecipient: null,
    keyword: '',
    generatedGreetings: [],
    selectedGreeting: null,
    selectedCardTemplate: null,
    cardText: '',
    fontSize: 24,
    textColor: '#8B0000',
    isGenerating: false,
  }),
}));

export default useGreetingStore;
