import { Settings2, ZoomIn, ZoomOut, Palette } from 'lucide-react';
import useGreetingStore from '../hooks/useGreetingStore';

const CardEditor = () => {
  const { cardText, setCardText, fontSize, setFontSize, textColor, setTextColor, selectedCardTemplate } = useGreetingStore();

  const colorOptions = [
    '#8B0000', '#FF6B6B', '#FF8FAB', '#FFB6C1', '#9B59B6', '#4169E1',
    '#2E8B57', '#FFD700', '#8B4513', '#000000', '#FFFFFF', '#666666'
  ];

  return (
    <section className="py-8 px-4 bg-gradient-to-b from-pink-50/30 to-white">
      <div className="max-w-4xl mx-auto">
        <h2 className="text-xl font-bold text-gray-800 mb-6 flex items-center gap-2">
          <span className="w-1 h-6 bg-gradient-to-b from-pink-400 to-pink-600 rounded-full"></span>
          编辑贺卡
        </h2>
        
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <div className="bg-white rounded-2xl shadow-lg p-6">
            <div className="flex items-center gap-2 mb-4">
              <Settings2 className="w-5 h-5 text-pink-500" />
              <h3 className="font-semibold text-gray-800">文字编辑</h3>
            </div>
            
            <textarea
              value={cardText}
              onChange={(e) => setCardText(e.target.value)}
              placeholder="输入贺卡文字内容..."
              className="w-full h-32 px-4 py-3 rounded-xl border border-gray-200 focus:border-pink-400 focus:ring-2 focus:ring-pink-200 outline-none transition-all resize-none"
            />
            
            <div className="mt-6">
              <div className="flex items-center gap-2 mb-3">
                <ZoomIn className="w-4 h-4 text-gray-500" />
                <span className="text-sm text-gray-600">字体大小</span>
                <span className="ml-auto text-sm font-medium text-pink-500">{fontSize}px</span>
              </div>
              <input
                type="range"
                min="16"
                max="48"
                value={fontSize}
                onChange={(e) => setFontSize(Number(e.target.value))}
                className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-pink-500"
              />
              <div className="flex justify-between text-xs text-gray-400 mt-1">
                <span>16px</span>
                <span>48px</span>
              </div>
            </div>
            
            <div className="mt-6">
              <div className="flex items-center gap-2 mb-3">
                <Palette className="w-4 h-4 text-gray-500" />
                <span className="text-sm text-gray-600">文字颜色</span>
              </div>
              <div className="flex flex-wrap gap-2">
                {colorOptions.map((color) => (
                  <button
                    key={color}
                    onClick={() => setTextColor(color)}
                    className={`w-10 h-10 rounded-full transition-all ${
                      textColor === color ? 'ring-2 ring-pink-500 ring-offset-2 scale-110' : 'hover:scale-110'
                    }`}
                    style={{ backgroundColor: color }}
                  />
                ))}
              </div>
            </div>
          </div>
          
          <div className="bg-white rounded-2xl shadow-lg p-6">
            <div className="flex items-center gap-2 mb-4">
              <span className="text-2xl">👀</span>
              <h3 className="font-semibold text-gray-800">实时预览</h3>
            </div>
            
            <div
              className="aspect-[3/4] rounded-xl overflow-hidden flex flex-col items-center justify-center p-8 relative"
              style={{
                background: selectedCardTemplate?.background || 'linear-gradient(135deg, #FFE4E1 0%, #FFB6C1 100%)'
              }}
            >
              <div className="absolute top-4 left-4 text-4xl opacity-30">
                ✨
              </div>
              <div className="absolute top-4 right-4 text-4xl opacity-30">
                💝
              </div>
              <div className="absolute bottom-4 left-4 text-4xl opacity-30">
                🌟
              </div>
              <div className="absolute bottom-4 right-4 text-4xl opacity-30">
                🎀
              </div>
              
              <div className="text-center z-10">
                {cardText ? (
                  <p
                    className="leading-relaxed max-w-full"
                    style={{
                      fontSize: `${fontSize}px`,
                      color: textColor,
                      textShadow: textColor === '#FFFFFF' ? '1px 1px 2px rgba(0,0,0,0.3)' : 'none'
                    }}
                  >
                    {cardText}
                  </p>
                ) : (
                  <p className="text-gray-400 text-lg">请先输入文字或选择祝福语</p>
                )}
              </div>
            </div>
            
            {selectedCardTemplate && (
              <div className="mt-4 text-center">
                <span className="inline-block px-3 py-1 bg-pink-100 text-pink-600 rounded-full text-sm">
                  当前模板：{selectedCardTemplate.title}
                </span>
              </div>
            )}
          </div>
        </div>
      </div>
    </section>
  );
};

export default CardEditor;
