export const generateGreetings = (sceneId: string, recipientId: string, keyword: string): GeneratedGreeting[] => {
  const templates = greetingTemplates[sceneId]?.[recipientId] || greetingTemplates.birthday.family;
  const styles = greetingStyles;
  
  return styles.map((style) => {
    const styleTemplates = templates[style.id] || templates.formal;
    const randomTemplate = styleTemplates[Math.floor(Math.random() * styleTemplates.length)];
    const greetingText = randomTemplate.replace(/{name}/g, keyword || '亲爱的');
    return {
      id: `${style.id}-${Date.now()}-${Math.random()}`,
      text: greetingText,
      style: style.name,
    };
  });
};
