import { useState } from 'react';
import { Sparkles, Copy, Check, RefreshCw } from 'lucide-react';
import useGreetingStore from '../hooks/useGreetingStore';
import { generateGreetings } from '../utils/mockData';

const GreetingGenerator = () => {
  const { selectedScene, selectedRecipient, keyword, setKeyword, generatedGreetings, setGeneratedGreetings, setSelectedGreeting, setCardText, setIsGenerating, isGenerating } = useGreetingStore();
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [allCopied, setAllCopied] = useState(false);

  const handleGenerate = async () => {
    if (!selectedScene || !selectedRecipient) {
      alert('请先选择场景和祝福对象');
      return;
    }
    
    setIsGenerating(true);
    
    await new Promise(resolve => setTimeout(resolve, 1500));
    
    const greetings = generateGreetings(selectedScene.id, selectedRecipient.id, keyword);
    setGeneratedGreetings(greetings);
    setIsGenerating(false);
  };

  const handleCopy = async (id: string, text: string) => {
    await navigator.clipboard.writeText(text);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const handleCopyAll = async () => {
    const allText = generatedGreetings.map(g => g.text).join('\n\n');
    await navigator.clipboard.writeText(allText);
    setAllCopied(true);
    setTimeout(() => setAllCopied(false), 2000);
  };

  const handleSelectGreeting = (greeting: typeof generatedGreetings[0]) => {
    setSelectedGreeting(greeting);
    setCardText(greeting.text);
  };

  const styleColors: Record<string, string> = {
    '正式': 'bg-blue-100 text-blue-700',
    '可爱': 'bg-pink-100 text-pink-700',
    '文艺': 'bg-purple-100 text-purple-700',
    '简约': 'bg-gray-100 text-gray-700',
    '搞怪': 'bg-yellow-100 text-yellow-700',
  };

  return (
    <section className="py-8 px-4 bg-gradient-to-b from-white to-pink-50/30">
      <div className="max-w-4xl mx-auto">
        <h2 className="text-xl font-bold text-gray-800 mb-6 flex items-center gap-2">
          <span className="w-1 h-6 bg-gradient-to-b from-pink-400 to-pink-600 rounded-full"></span>
          祝福语生成
        </h2>
        
        <div className="bg-white rounded-2xl shadow-lg p-6 mb-6">
          <div className="flex flex-col md:flex-row gap-4">
            <div className="flex-1 relative">
              <input
                type="text"
                value={keyword}
                onChange={(e) => setKeyword(e.target.value)}
                placeholder="输入关键词（如姓名、昵称等，可选）"
                className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:border-pink-400 focus:ring-2 focus:ring-pink-200 outline-none transition-all"
              />
            </div>
            <button
              onClick={handleGenerate}
              disabled={isGenerating}
              className="px-6 py-3 bg-gradient-to-r from-pink-500 to-rose-500 text-white rounded-xl font-medium hover:from-pink-600 hover:to-rose-600 transition-all duration-300 flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed shadow-lg hover:shadow-xl"
            >
              {isGenerating ? (
                <>
                  <RefreshCw className="w-5 h-5 animate-spin" />
                  生成中...
                </>
              ) : (
                <>
                  <Sparkles className="w-5 h-5" />
                  AI生成
                </>
              )}
            </button>
          </div>
          
          {!selectedScene && (
            <p className="mt-3 text-sm text-orange-500 flex items-center gap-1">
              <span>⚠️</span> 请先选择场景
            </p>
          )}
          {selectedScene && !selectedRecipient && (
            <p className="mt-3 text-sm text-orange-500 flex items-center gap-1">
              <span>⚠️</span> 请先选择祝福对象
            </p>
          )}
        </div>

        {generatedGreetings.length > 0 && (
          <>
            <div className="flex items-center justify-between mb-4">
              <p className="text-gray-600 text-sm">生成了 {generatedGreetings.length} 条祝福语</p>
              <button
                onClick={handleCopyAll}
                className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-sm transition-all ${
                  allCopied
                    ? 'bg-green-100 text-green-600'
                    : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                }`}
              >
                {allCopied ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                {allCopied ? '已复制全部' : '批量复制'}
              </button>
            </div>
            
            <div className="space-y-4">
              {generatedGreetings.map((greeting) => (
                <div
                  key={greeting.id}
                  className="bg-white rounded-xl p-5 shadow-md hover:shadow-lg transition-all duration-300 border border-gray-100"
                >
                  <div className="flex items-start justify-between gap-4">
                    <div className="flex-1">
                      <span className={`inline-block px-2.5 py-1 rounded-full text-xs font-medium mb-3 ${styleColors[greeting.style] || 'bg-gray-100 text-gray-700'}`}>
                        {greeting.style}
                      </span>
                      <p className="text-gray-800 leading-relaxed">{greeting.text}</p>
                    </div>
                    <div className="flex flex-col gap-2">
                      <button
                        onClick={() => handleSelectGreeting(greeting)}
                        className="px-4 py-2 bg-gradient-to-r from-pink-400 to-pink-500 text-white text-sm rounded-lg hover:from-pink-500 hover:to-pink-600 transition-all"
                      >
                        选中
                      </button>
                      <button
                        onClick={() => handleCopy(greeting.id, greeting.text)}
                        className={`p-2 rounded-lg transition-all ${
                          copiedId === greeting.id
                            ? 'bg-green-100 text-green-600'
                            : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                        }`}
                      >
                        {copiedId === greeting.id ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </>
        )}
      </div>
    </section>
  );
};

export default GreetingGenerator;
